export type WorkspaceView = 'board' | 'list' | 'timeline';

type Props = { value: WorkspaceView; dispatch: (action: { type: 'workspace/viewChanged'; view: WorkspaceView }) => void };
const views: WorkspaceView[] = ['board', 'list', 'timeline'];

export function WorkspaceViewChoice({ value, dispatch }: Props) {
  return <div className="view-choice" role="radiogroup" aria-label="Workspace view">
    {views.map(view => <button key={view} type="button" role="radio" aria-checked={value === view} className={value === view ? 'selected' : ''} onClick={() => dispatch({ type: 'workspace/viewChanged', view })}>{view[0].toUpperCase() + view.slice(1)}</button>)}
  </div>;
}
